import java.util.Arrays;
import java.util.NoSuchElementException;

final class IntBinaryHeap {
    private static final int DEFAULT_CAPACITY = 10;

    private int[] elements;
    private int size;

    IntBinaryHeap() {
        this(DEFAULT_CAPACITY);
    }

    IntBinaryHeap(int initialCapacity) {
        if (initialCapacity < 0) {
            throw new IllegalArgumentException("initial capacity must be non-negative");
        }

        elements = new int[initialCapacity];
        size = 0;
    }

    IntBinaryHeap(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("values must not be null");
        }

        elements = copyOf(values);
        size = values.length;
        rebuildHeap();
    }

    boolean offer(int value) {
        ensureCapacity(size + 1);
        elements[size] = value;
        siftUp(size);
        size++;
        return true;
    }

    void addAll(int... values) {
        if (values == null) {
            throw new IllegalArgumentException("values must not be null");
        }

        if (values.length == 0) {
            return;
        }

        appendAll(values);
        rebuildHeap();
    }

    int peek() {
        ensureNotEmpty();
        return elements[0];
    }

    int removeMin() {
        ensureNotEmpty();
        return removeAt(0);
    }

    int removeAt(int index) {
        validateOccupiedIndex(index);

        int removedValue = elements[index];
        int lastIndex = size - 1;
        int lastValue = elements[lastIndex];
        elements[lastIndex] = 0;
        size--;
        if (index == lastIndex) {
            return removedValue;
        }

        elements[index] = lastValue;
        restoreHeapAt(index);
        return removedValue;
    }

    void updateValue(int index, int newValue) {
        validateOccupiedIndex(index);

        int currentValue = elements[index];
        elements[index] = newValue;
        if (newValue < currentValue) {
            siftUp(index);
            return;
        }

        if (newValue > currentValue) {
            siftDown(index);
        }
    }

    void clear() {
        Arrays.fill(elements, 0, size, 0);
        size = 0;
    }

    boolean isEmpty() {
        return size == 0;
    }

    int size() {
        return size;
    }

    int capacity() {
        return elements.length;
    }

    int valueAt(int index) {
        validateOccupiedIndex(index);
        return elements[index];
    }

    int[] toArray() {
        return copyOf(elements, size);
    }

    private void appendAll(int[] values) {
        int originalSize = size;
        ensureCapacity(originalSize + values.length);
        System.arraycopy(values, 0, elements, originalSize, values.length);
        size += values.length;
    }

    private void rebuildHeap() {
        for (int index = parentIndex(size - 1); index >= 0; index--) {
            siftDown(index);
        }
    }

    private void ensureCapacity(int requiredCapacity) {
        if (requiredCapacity <= elements.length) {
            return;
        }

        int newCapacity = elements.length == 0 ? 1 : elements.length;
        while (newCapacity < requiredCapacity) {
            newCapacity *= 2;
        }

        elements = Arrays.copyOf(elements, newCapacity);
    }

    private void siftUp(int index) {
        while (index > 0) {
            int parentIndex = parentIndex(index);
            if (elements[parentIndex] <= elements[index]) {
                return;
            }

            swap(index, parentIndex);
            index = parentIndex;
        }
    }

    private void siftDown(int index) {
        while (true) {
            int leftChildIndex = leftChildIndex(index);
            int rightChildIndex = rightChildIndex(index);
            int smallestIndex = index;

            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
                smallestIndex = leftChildIndex;
            }

            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
                smallestIndex = rightChildIndex;
            }

            if (smallestIndex == index) {
                return;
            }

            swap(index, smallestIndex);
            index = smallestIndex;
        }
    }

    private void restoreHeapAt(int index) {
        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
            siftUp(index);
            return;
        }

        siftDown(index);
    }

    private void swap(int firstIndex, int secondIndex) {
        int temp = elements[firstIndex];
        elements[firstIndex] = elements[secondIndex];
        elements[secondIndex] = temp;
    }

    private void ensureNotEmpty() {
        if (isEmpty()) {
            throw new NoSuchElementException("heap is empty");
        }
    }

    private void validateOccupiedIndex(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "index " + index + " is outside heap size " + size
            );
        }
    }

    private int parentIndex(int index) {
        return (index - 1) / 2;
    }

    private int leftChildIndex(int index) {
        return index * 2 + 1;
    }

    private int rightChildIndex(int index) {
        return index * 2 + 2;
    }

    private static int[] copyOf(int[] values) {
        return copyOf(values, values.length);
    }

    private static int[] copyOf(int[] values, int length) {
        return Arrays.copyOf(values, length);
    }
}

import java.util.NoSuchElementException;
import java.util.OptionalInt;

public class MinHeapTest {
    public static void main(String[] args) {
        testDefaultConstructorProvidesUsableHeap();
        testFactoryBuildsHeapFromValues();
        testCopyFactoryDuplicatesHeapContents();
        testInterfaceContractSupportsBulkInsert();
        testPollMinReturnsOptionalValues();
        testExampleFlow();
        testQueueStyleApi();
        testHeapGrowsBeyondInitialCapacity();
        testBulkConstructionHeapifiesInput();
        testBulkConstructionDefensivelyCopiesInput();
        testRemoveAtRestoresHeapOrder();
        testChangeValueReordersBothDirections();
        testDirectionalUpdatesRejectInvalidValues();
        testInvalidIndexFailsFast();
        testClearResetsHeapState();
        testToArrayReturnsDefensiveCopy();
        testEmptyHeapBehavior();
        System.out.println("All MinHeap tests passed.");
    }

    private static void testDefaultConstructorProvidesUsableHeap() {
        MinHeap heap = new MinHeap();
        heap.offer(6);
        heap.offer(2);

        assertEquals("default constructor should create a working heap", 2, heap.peek());
    }

    private static void testFactoryBuildsHeapFromValues() {
        MinHeap heap = MinHeap.from(6, 2, 9, 1);
        assertArrayEquals(
            "factory should build a valid heap",
            new int[] {1, 2, 6, 9},
            heap.drainToArray()
        );
    }

    private static void testCopyFactoryDuplicatesHeapContents() {
        MinHeap original = MinHeap.from(7, 3, 9, 1);
        MinHeap copy = MinHeap.copyOf(original);

        assertEquals("copy factory should preserve original size", 4, copy.size());
        assertEquals("copy factory should not mutate the source heap", 1, original.peek());
        assertArrayEquals(
            "copy factory should preserve heap ordering",
            new int[] {1, 3, 7, 9},
            copy.drainToArray()
        );
    }

    private static void testInterfaceContractSupportsBulkInsert() {
        IntHeap heap = new MinHeap();
        heap.addAll(6, 2, 9, 1);

        assertEquals("interface bulk insert should update size", 4, heap.size());
        assertEquals("interface bulk insert should preserve minimum", 1, heap.peek());
        assertEquals("interface removeMin should return the minimum", 1, heap.removeMin());
    }

    private static void testPollMinReturnsOptionalValues() {
        IntHeap heap = MinHeap.from(4, 1);
        assertEquals("pollMin should return the minimum when present", 1, heap.pollMin().orElseThrow());
        assertEquals("pollMin should return the next minimum", 4, heap.pollMin().orElseThrow());
        assertOptionalEmpty("pollMin should return empty when the heap is drained", heap.pollMin());
    }

    @SuppressWarnings("deprecation")
    private static void testExampleFlow() {
        LegacyMinHeapApi heap = new MinHeap(11);
        heap.insertKey(3);
        heap.insertKey(2);
        heap.deleteKey(1);
        heap.insertKey(15);
        heap.insertKey(5);
        heap.insertKey(4);
        heap.insertKey(45);

        assertEquals("extractMin should match original example", 2, heap.extractMin());
        assertEquals("getMin should match original example", 4, heap.getMin());

        heap.decreaseKey(2, 1);
        assertEquals("decreaseKey should promote the new minimum", 1, heap.getMin());
    }

    private static void testQueueStyleApi() {
        MinHeap heap = new MinHeap(4);
        assertTrue("offer should insert first value", heap.offer(9));
        assertTrue("offer should insert second value", heap.offer(3));
        assertTrue("offer should insert third value", heap.offer(7));
        assertEquals("peek should expose the minimum", 3, heap.peek());
        assertEquals("removeMin should return the minimum", 3, heap.removeMin());
        assertEquals("peek should update after removal", 7, heap.peek());
    }

    @SuppressWarnings("deprecation")
    private static void testHeapGrowsBeyondInitialCapacity() {
        LegacyMinHeapApi heap = new MinHeap(1);
        heap.offer(10);
        assertTrue(
            "legacy isFull should reflect when the current backing array is saturated",
            heap.isFull()
        );

        heap.offer(4);
        heap.offer(7);

        assertEquals("size should include all inserted values", 3, heap.size());
        assertTrue("capacity should grow to fit additional values", heap.capacity() >= 3);
        assertArrayEquals(
            "growth should preserve heap ordering",
            new int[] {4, 7, 10},
            heap.drainToArray()
        );
    }

    private static void testBulkConstructionHeapifiesInput() {
        MinHeap heap = new MinHeap(new int[] {8, 3, 9, 1, 4});
        assertEquals("bulk constructor should heapify input", 1, heap.peek());
        assertArrayEquals(
            "bulk constructor should produce sorted removals",
            new int[] {1, 3, 4, 8, 9},
            heap.drainToArray()
        );
    }

    private static void testBulkConstructionDefensivelyCopiesInput() {
        int[] values = {8, 3, 9, 1, 4};
        MinHeap heap = new MinHeap(values);
        values[0] = -10;

        assertEquals("constructor should copy input values", 1, heap.peek());
    }

    private static void testRemoveAtRestoresHeapOrder() {
        MinHeap heap = new MinHeap(6);
        heap.offer(1);
        heap.offer(4);
        heap.offer(2);
        heap.offer(9);
        heap.offer(7);

        assertEquals("removeAt should return the removed value", 4, heap.removeAt(1));
        assertEquals("removal should preserve the heap minimum", 1, heap.peek());
        assertArrayEquals(
            "heap order should remain valid after removeAt",
            new int[] {1, 2, 7, 9},
            heap.drainToArray()
        );
    }

    @SuppressWarnings("deprecation")
    private static void testChangeValueReordersBothDirections() {
        LegacyMinHeapApi heap = new MinHeap(5);
        heap.insertKey(8);
        heap.insertKey(4);
        heap.insertKey(6);
        heap.insertKey(10);

        heap.updateValue(3, 1);
        assertEquals("lowering a value should bubble it up", 1, heap.getMin());

        heap.updateValue(0, 12);
        assertEquals("raising the root should restore heap order", 4, heap.getMin());
    }

    @SuppressWarnings("deprecation")
    private static void testDirectionalUpdatesRejectInvalidValues() {
        LegacyMinHeapApi heap = new MinHeap(3);
        heap.offer(5);
        heap.offer(9);

        assertThrows(
            "decreaseKey should reject larger values",
            IllegalArgumentException.class,
            () -> heap.decreaseKey(1, 12)
        );

        assertThrows(
            "increaseKey should reject smaller values",
            IllegalArgumentException.class,
            () -> heap.increaseKey(1, 1)
        );
    }

    @SuppressWarnings("deprecation")
    private static void testInvalidIndexFailsFast() {
        LegacyMinHeapApi heap = new MinHeap(3);
        heap.insertKey(5);

        assertThrows(
            "deleteKey should reject invalid indexes",
            IndexOutOfBoundsException.class,
            () -> heap.deleteKey(2)
        );

        assertThrows(
            "valueAt should reject invalid indexes",
            IndexOutOfBoundsException.class,
            () -> heap.valueAt(-1)
        );
    }

    private static void testClearResetsHeapState() {
        MinHeap heap = new MinHeap(new int[] {5, 2, 8});
        heap.clear();

        assertTrue("clear should empty the heap", heap.isEmpty());
        assertEquals("clear should reset size", 0, heap.size());
        assertEquals("clear should keep current capacity available", 3, heap.capacity());
        assertTrue("toArray should be empty after clear", heap.toArray().length == 0);
    }

    private static void testToArrayReturnsDefensiveCopy() {
        MinHeap heap = new MinHeap(new int[] {6, 1, 3});
        int[] snapshot = heap.toArray();
        snapshot[0] = 99;

        assertEquals("mutating a snapshot should not affect the heap", 1, heap.peek());
    }

    @SuppressWarnings("deprecation")
    private static void testEmptyHeapBehavior() {
        LegacyMinHeapApi heap = new MinHeap(1);

        assertThrows(
            "peek should reject an empty heap",
            NoSuchElementException.class,
            heap::peek
        );

        assertThrows(
            "removeMin should reject an empty heap",
            NoSuchElementException.class,
            heap::removeMin
        );

        assertEquals(
            "extractMin should preserve legacy empty-heap behavior",
            Integer.MAX_VALUE,
            heap.extractMin()
        );
    }

    private static void assertArrayEquals(String message, int[] expected, int[] actual) {
        if (expected.length != actual.length) {
            throw new AssertionError(
                message + ": expected length " + expected.length + ", got " + actual.length
            );
        }

        for (int index = 0; index < expected.length; index++) {
            if (expected[index] != actual[index]) {
                throw new AssertionError(
                    message + ": mismatch at index " + index + ", expected "
                        + expected[index] + ", got " + actual[index]
                );
            }
        }
    }

    private static void assertOptionalEmpty(String message, OptionalInt actual) {
        if (actual.isPresent()) {
            throw new AssertionError(message + ": expected empty optional, got " + actual.getAsInt());
        }
    }

    private static void assertEquals(String message, int expected, int actual) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + ", got " + actual);
        }
    }

    private static void assertTrue(String message, boolean condition) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void assertThrows(
        String message,
        Class<? extends Throwable> expectedType,
        ThrowingRunnable action
    ) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (expectedType.isInstance(thrown)) {
                return;
            }

            throw new AssertionError(
                message + ": expected " + expectedType.getSimpleName()
                    + ", got " + thrown.getClass().getSimpleName(),
                thrown
            );
        }

        throw new AssertionError(
            message + ": expected " + expectedType.getSimpleName() + " to be thrown"
        );
    }

    @FunctionalInterface
    private interface ThrowingRunnable {
        void run();
    }
}

