  4	final class IntBinaryHeap {
  5	    private static final int DEFAULT_CAPACITY = 10;
  6	
  7	    private int[] elements;
  8	    private int size;
  9	
 10	    IntBinaryHeap() {
 11	        this(new int[DEFAULT_CAPACITY], 0, false);
 12	    }
 13	
 14	    IntBinaryHeap(int initialCapacity) {
 15	        this(new int[validateInitialCapacity(initialCapacity)], 0, false);
 16	    }
 17	
 18	    IntBinaryHeap(int[] values) {
 19	        this(copyInput(values), values.length, true);
 20	    }
 21	
 22	    private IntBinaryHeap(int[] elements, int size, boolean needsHeapify) {
 23	        this.elements = elements;
 24	        this.size = size;
 25	        if (needsHeapify) {
 26	            rebuildHeap();
 27	        }
 28	    }
 29	
 30	    boolean offer(int value) {
 31	        ensureCapacity(size + 1);
 32	        elements[size] = value;
 33	        siftUp(size);
 34	        size++;
 35	        return true;
 36	    }
 37	
 38	    void addAll(int... values) {
 39	        if (values == null) {
 40	            throw new IllegalArgumentException("values must not be null");
 41	        }
 42	
 43	        if (values.length == 0) {
 44	            return;
 45	        }
 46	
 47	        appendAll(values);
 48	        rebuildHeap();
 49	    }
 50	
 51	    int peek() {
 52	        ensureNotEmpty();
 53	        return elements[0];
 54	    }
 55	
 56	    int removeMin() {
 57	        ensureNotEmpty();
 58	        return removeAt(0);
 59	    }
 60	
 61	    int replaceMin(int value) {
 62	        ensureNotEmpty();
 63	        int previousMin = elements[0];
 64	        elements[0] = value;
 65	        siftDown(0);
 66	        return previousMin;
 67	    }
 68	
 69	    int removeAt(int index) {
 70	        validateOccupiedIndex(index);
 71	
 72	        int removedValue = elements[index];
 73	        int lastIndex = size - 1;
 74	        int lastValue = elements[lastIndex];
 75	        elements[lastIndex] = 0;
 76	        size--;
 77	        if (index == lastIndex) {
 78	            return removedValue;
 79	        }
 80	
 81	        elements[index] = lastValue;
 82	        restoreHeapAt(index);
 83	        return removedValue;
 84	    }
 85	
 86	    void updateValue(int index, int newValue) {
 87	        validateOccupiedIndex(index);
 88	
 89	        int currentValue = elements[index];
 90	        elements[index] = newValue;
 91	        if (newValue < currentValue) {
 92	            siftUp(index);
 93	            return;
 94	        }
 95	
 96	        if (newValue > currentValue) {
 97	            siftDown(index);
 98	        }
 99	    }
100	
101	    void clear() {
102	        Arrays.fill(elements, 0, size, 0);
103	        size = 0;
104	    }
105	
106	    boolean isEmpty() {
107	        return size == 0;
108	    }
109	
110	    int size() {
111	        return size;
112	    }
113	
114	    int capacity() {
115	        return elements.length;
116	    }
117	
118	    int valueAt(int index) {
119	        validateOccupiedIndex(index);
120	        return elements[index];
121	    }
122	
123	    int[] toArray() {
124	        return copyOf(elements, size);
125	    }
126	
127	    private void appendAll(int[] values) {
128	        int originalSize = size;
129	        ensureCapacity(originalSize + values.length);
130	        System.arraycopy(values, 0, elements, originalSize, values.length);
131	        size += values.length;
132	    }
133	
134	    private void rebuildHeap() {
135	        for (int index = parentIndex(size - 1); index >= 0; index--) {
136	            siftDown(index);
137	        }
138	    }
139	
140	    private void ensureCapacity(int requiredCapacity) {
141	        if (requiredCapacity <= elements.length) {
142	            return;
143	        }
144	
145	        int newCapacity = elements.length == 0 ? 1 : elements.length;
146	        while (newCapacity < requiredCapacity) {
147	            newCapacity *= 2;
148	        }
149	
150	        elements = Arrays.copyOf(elements, newCapacity);
151	    }
152	
153	    private void siftUp(int index) {
154	        while (index > 0) {
155	            int parentIndex = parentIndex(index);
156	            if (elements[parentIndex] <= elements[index]) {
157	                return;
158	            }
159	
160	            swap(index, parentIndex);
161	            index = parentIndex;
162	        }
163	    }
164	
165	    private void siftDown(int index) {
166	        while (true) {
167	            int leftChildIndex = leftChildIndex(index);
168	            int rightChildIndex = rightChildIndex(index);
169	            int smallestIndex = index;
170	
171	            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
172	                smallestIndex = leftChildIndex;
173	            }
174	
175	            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
176	                smallestIndex = rightChildIndex;
177	            }
178	
179	            if (smallestIndex == index) {
180	                return;
181	            }
182	
183	            swap(index, smallestIndex);
184	            index = smallestIndex;
185	        }
186	    }
187	
188	    private void restoreHeapAt(int index) {
189	        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
190	            siftUp(index);
191	            return;
192	        }
193	
194	        siftDown(index);
195	    }
196	
197	    private void swap(int firstIndex, int secondIndex) {
198	        int temp = elements[firstIndex];
199	        elements[firstIndex] = elements[secondIndex];
200	        elements[secondIndex] = temp;
201	    }
202	
203	    private void ensureNotEmpty() {
204	        if (isEmpty()) {
205	            throw new NoSuchElementException("heap is empty");
206	        }
207	    }
208	
209	    private void validateOccupiedIndex(int index) {
210	        if (index < 0 || index >= size) {
211	            throw new IndexOutOfBoundsException(
212	                "index " + index + " is outside heap size " + size
213	            );
214	        }
215	    }
216	
217	    private int parentIndex(int index) {
218	        return (index - 1) / 2;
219	    }
220	
221	    private int leftChildIndex(int index) {
222	        return index * 2 + 1;
223	    }
224	
225	    private int rightChildIndex(int index) {
226	        return index * 2 + 2;
227	    }
228	
229	    private static int[] copyOf(int[] values) {
230	        return copyOf(values, values.length);
231	    }
232	
233	    private static int[] copyOf(int[] values, int length) {
234	        return Arrays.copyOf(values, length);
235	    }
236	
237	    private static int validateInitialCapacity(int initialCapacity) {
238	        if (initialCapacity < 0) {
239	            throw new IllegalArgumentException("initial capacity must be non-negative");
240	        }
241	
242	        return initialCapacity;
243	    }
244	
245	    private static int[] copyInput(int[] values) {
246	        if (values == null) {
247	            throw new IllegalArgumentException("values must not be null");
248	        }
249	
250	        return copyOf(values);
251	    }
252	}

